def net_price(price, pct=10):
    return price * (100 - pct) / 100

parts = input().split()
price = float(parts[0])
if len(parts) == 2:
    print(f"{net_price(price, int(parts[1])):.2f}")
else:
    print(f"{net_price(price):.2f}")

def shipping_cost(weight, base=20, rate=5, surcharge=0):
    return base + weight * rate + surcharge

weight = float(input())
mode = input()
if mode == "express":
    total = shipping_cost(weight, surcharge=50)
else:
    total = shipping_cost(weight)
print(f"{total:.2f}")

def bonus(salary, pct=5.0):
    return salary * pct / 100

salary = float(input())
role = input()
if role == "manager":
    print(f"{bonus(salary, 12):.2f}")
elif role == "lead":
    print(f"{bonus(salary, 8):.2f}")
else:
    print(f"{bonus(salary):.2f}")

def bill(units):
    if units <= 100:
        return units * 3.5
    if units <= 200:
        return 350 + (units - 100) * 5
    return 850 + (units - 200) * 8

n = int(input())
for _ in range(n):
    u = int(input())
    print(f"{bill(u):.2f}")

def base_fee(days):
    if days <= 7:
        return days * 0.5
    return 3.5 + extra_fee(days)

def extra_fee(days):
    if days <= 30:
        return (days - 7) * 1.0
    return 23.0 + heavy_fee(days - 30)

def heavy_fee(d):
    return d * 2.0

n = int(input())
for _ in range(n):
    d = int(input())
    print(f"{base_fee(d):.2f}")

def build_order(size, **extras):
    names = []
    for t in extras:
        names.append(t)
    if names:
        return size + " pizza with " + ", ".join(names)
    return size + " pizza (plain)"

size = input()
count = int(input())
toppings = {}
for _ in range(count):
    toppings[input()] = True
print(build_order(size, **toppings))

def make_converter(rate):
    def convert(amount):
        return amount * rate
    return convert

rates = {}
m = int(input())
for _ in range(m):
    parts = input().split()
    rates[parts[0]] = float(parts[1])

q = int(input())
for _ in range(q):
    parts = input().split()
    code = parts[0]
    amount = float(parts[1])
    if code in rates:
        converter = make_converter(rates[code])
        print(f"{converter(amount):.2f}")
    else:
        print("Unknown currency")
